import uuid
from datetime import UTC, date, datetime

from sqlalchemy import JSON, Date, DateTime, Float, ForeignKey, Index, MetaData, Text
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship

# Named constraints: without this, autogenerated migrations contain anonymous constraints
# that cannot be dropped portably later.
NAMING = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING)


def _utcnow() -> datetime:
    return datetime.now(UTC)


def _new_id() -> str:
    return uuid.uuid4().hex


class User(Base):
    """A person. `sub` is Google's stable account id and the real identity; email is only a label
    (addresses get renamed and recycled). A row with no `sub` is an invitation: the first Google
    login with that verified email claims it."""

    __tablename__ = "users"

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    sub: Mapped[str | None] = mapped_column(unique=True, default=None)
    email: Mapped[str] = mapped_column(unique=True)  # always stored lower-case
    name: Mapped[str | None] = mapped_column(default=None)
    picture: Mapped[str | None] = mapped_column(default=None)
    role: Mapped[str] = mapped_column(default="user")  # "user" | "superadmin"
    disabled: Mapped[bool] = mapped_column(default=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    last_login_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)


class AuthSession(Base):
    """A logged-in browser or desktop app. Only the SHA-256 of the token is stored, so a leaked
    database does not leak usable sessions."""

    __tablename__ = "auth_sessions"

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    user_id: Mapped[str] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), index=True)
    token_hash: Mapped[str] = mapped_column(unique=True)
    kind: Mapped[str] = mapped_column(default="web")  # "web" (cookie) | "desktop" (bearer)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    last_seen_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)


class AuthFlow(Base):
    """One in-progress Google login, from /auth/login to /auth/callback. Single use, short-lived,
    and bound to the browser that started it (login-CSRF defence, since PKCE alone cannot tell)."""

    __tablename__ = "auth_flows"

    state: Mapped[str] = mapped_column(primary_key=True)
    nonce: Mapped[str]
    code_verifier: Mapped[str]
    binding_hash: Mapped[str]
    redirect_to: Mapped[str] = mapped_column(default="/")
    desktop_port: Mapped[int | None] = mapped_column(default=None)
    desktop_challenge: Mapped[str | None] = mapped_column(default=None)
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    used: Mapped[bool] = mapped_column(default=False)


class LoginCode(Base):
    """Hands a finished browser login to the desktop app on its loopback port. Single use, ~2
    minutes, and redeemable only with the PKCE verifier the desktop generated."""

    __tablename__ = "login_codes"

    code_hash: Mapped[str] = mapped_column(primary_key=True)
    user_id: Mapped[str] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"))
    challenge: Mapped[str]
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    used: Mapped[bool] = mapped_column(default=False)


class Meeting(Base):
    __tablename__ = "meetings"

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    title: Mapped[str]
    # NULL only for rows that predate accounts; those are visible to super admins alone.
    owner_id: Mapped[str | None] = mapped_column(ForeignKey("users.id"), index=True, default=None)
    language: Mapped[str] = mapped_column(default="id")
    # recording -> recorded -> queued -> processing -> review -> done, or failed
    status: Mapped[str] = mapped_column(default="recording")
    local_user_name: Mapped[str | None] = mapped_column(default=None)
    started_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    ended_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)
    error: Mapped[str | None] = mapped_column(Text, default=None)
    deleted_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)

    owner: Mapped["User | None"] = relationship(lazy="joined")
    participants: Mapped[list["Participant"]] = relationship(back_populates="meeting", cascade="all, delete-orphan")
    segments: Mapped[list["Segment"]] = relationship(
        back_populates="meeting", cascade="all, delete-orphan", order_by="Segment.start_ms"
    )
    tasks: Mapped[list["Task"]] = relationship(back_populates="meeting", cascade="all, delete-orphan")
    summary: Mapped["Summary | None"] = relationship(
        back_populates="meeting", uselist=False, cascade="all, delete-orphan"
    )



def _owner_email(self) -> str | None:
    return self.owner.email if self.owner else None


Meeting.owner_email = property(_owner_email)  # type: ignore[attr-defined]


class Participant(Base):
    """A speaker in one meeting. `label` is what diarization produced; `name`
    is what the user renamed it to, and what task assignees get matched against."""

    __tablename__ = "participants"

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    meeting_id: Mapped[str] = mapped_column(ForeignKey("meetings.id", ondelete="CASCADE"), index=True)
    label: Mapped[str]
    name: Mapped[str | None] = mapped_column(default=None)
    is_local_user: Mapped[bool] = mapped_column(default=False)

    meeting: Mapped[Meeting] = relationship(back_populates="participants")


class Segment(Base):
    __tablename__ = "segments"

    id: Mapped[int] = mapped_column(primary_key=True, autoincrement=True)
    meeting_id: Mapped[str] = mapped_column(ForeignKey("meetings.id", ondelete="CASCADE"), index=True)
    participant_id: Mapped[str | None] = mapped_column(ForeignKey("participants.id"), default=None)
    source: Mapped[str]  # "mic" | "speaker"
    start_ms: Mapped[int]
    end_ms: Mapped[int]
    text: Mapped[str] = mapped_column(Text)

    meeting: Mapped[Meeting] = relationship(back_populates="segments")


class Summary(Base):
    __tablename__ = "summaries"

    meeting_id: Mapped[str] = mapped_column(ForeignKey("meetings.id", ondelete="CASCADE"), primary_key=True)
    overview: Mapped[str] = mapped_column(Text, default="")
    decisions: Mapped[list] = mapped_column(JSON, default=list)
    minutes: Mapped[list] = mapped_column(JSON, default=list)

    meeting: Mapped[Meeting] = relationship(back_populates="summary")


class Task(Base):
    __tablename__ = "tasks"

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    meeting_id: Mapped[str] = mapped_column(ForeignKey("meetings.id", ondelete="CASCADE"), index=True)
    title: Mapped[str]
    description: Mapped[str] = mapped_column(Text, default="")
    # Both kept: the raw name the LLM heard, and the resolved participant if one matched.
    assignee_name: Mapped[str | None] = mapped_column(default=None)
    assignee_participant_id: Mapped[str | None] = mapped_column(ForeignKey("participants.id"), default=None)
    deadline_text: Mapped[str | None] = mapped_column(default=None)
    deadline: Mapped[date | None] = mapped_column(Date, default=None)
    deadline_approximate: Mapped[bool] = mapped_column(default=False)
    estimate_minutes: Mapped[int | None] = mapped_column(default=None)
    priority: Mapped[str] = mapped_column(default="medium")
    confidence: Mapped[float] = mapped_column(Float, default=0.5)
    evidence_start_ms: Mapped[int | None] = mapped_column(default=None)
    evidence_quote: Mapped[str] = mapped_column(Text, default="")
    # suggested -> confirmed | rejected. Only confirmed tasks are exportable.
    status: Mapped[str] = mapped_column(default="suggested")
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow, onupdate=_utcnow)

    meeting: Mapped[Meeting] = relationship(back_populates="tasks")


class Job(Base):
    __tablename__ = "jobs"
    __table_args__ = (Index("ix_jobs_status_created", "status", "created_at"),)

    id: Mapped[str] = mapped_column(primary_key=True, default=_new_id)
    meeting_id: Mapped[str] = mapped_column(ForeignKey("meetings.id", ondelete="CASCADE"), index=True)
    kind: Mapped[str] = mapped_column(default="process")
    status: Mapped[str] = mapped_column(default="queued")  # queued | running | done | failed
    stage: Mapped[str | None] = mapped_column(default=None)
    progress: Mapped[int] = mapped_column(default=0)  # 0..100
    attempts: Mapped[int] = mapped_column(default=0)
    error: Mapped[str | None] = mapped_column(Text, default=None)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)
    claimed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)
    finished_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), default=None)
